    for v,pos in seeds.items():
        for r,c in pos:
            # vertical periodic extension along rows
            for rr in range(0,h,S) if S else []:
                y,x=r+(rr%h if False else rr*c//c if False else rr), c
                y=r+rr
                if 0<=y<h and y not in urows and out[y][x]==bg: out[y][x]=v
            for cc in range(0,w,T) if T else []:
                y,x=r, c+cc
                if 0<=x<w and x not in ucols and out[y][x]==bg: out[y][x]=v
    return out
for n in (1,2,3):
