# my solve for demo3 failed only because periodicity of color5's own seeds was wrong: 5 appears in a regular checker pattern (period2) but expected fills period5. So the rule uses the separator spacing as the fill step, not seed spacing.
# Fix: use step = S (row-spacing between uniform rows) / T for each direction.
def solve(gi):
    h,w=len(gi),len(gi[0])
    bg=Counter(x for r_ in gi for x in r_).most_common(1)[0][0]
    urows=[r for r in range(h) if len(set(gi[r]))==1 and gi[r][0]!=bg]
    ucols=[c for c in range(w) if len(set(r[c] for r in gi))==1 and gi[0][c]!=bg]
    ur=sorted(urows); uc=sorted(ucols)
    S=max(ur[i+1]-ur[i] for i in range(len(ur)-1)) if len(ur)>1 else None
    T=max(uc[j+1]-uc[j] for j in range(len(uc)-1)) if len(uc)>1 else None
    out=[row[:] for row in gi]
    seeds=defaultdict(list)
    for r in range(h):
        for c in range(w):
            v=gi[r][c]
            if v!=bg and r not in urows and c not in ucols: seeds[v].append((r,c))
    for v,pos in seeds.items():
        for r,c in pos:
            for rr in range(-h,h,S):
                y=r+rr
                if 0<=y<h and y not in urows and out[y][c]==bg: out[y][c]=v
            for cc in range(-w,w,T):
                x=c+cc
                if 0<=x<w and x not in ucols and out[r][x]==bg: out[r][x]=v
    return out
