# Revert to the earlier version that matched demos 1,2 and was almost perfect on demo3 (only (5,0) wrong). That used: step = max gap, seed spans must be >= step.
def solve(gi):
    h,w=len(gi),len(gi[0])
    bg=Counter(x for r_ in gi for x in r_).most_common(1)[0][0]
    urows=[r for r in range(h) if len(set(gi[r]))==1 and gi[r][0]!=bg]
    ucols=[c for c in range(w) if len(set(r[c] for r in gi))==1 and gi[0][c]!=bg]
    ur=sorted(urows); uc=sorted(ucols)
    S=max(ur[i+1]-ur[i] for i in range(len(ur)-1)) if len(ur)>1 else None
    T=max(uc[j+1]-uc[j] for j in range(len(uc)-1)) if len(uc)>1 else None
    out=[row[:] for row in gi]
    cells=defaultdict(list)
    for r in range(h):
        for c in range(w):
            v=gi[r][c]
            if v!=bg and r not in urows and c not in ucols: cells[v].append((r,c))
    for v,pos in cells.items():
        verts=defaultdict(list); horzs=defaultdict(list)
        for r,c in pos: verts[c].append(r); horzs[r].append(c)
        for c,rs in verts.items():
            lo,hi=min(rs),max(rs)
            if S and hi-lo>=S:
                for rr in range(lo,hi+1,S):
                    y,x=rr,c
                    if y not in urows and out[y][x]!=v: out[y][x]=v
        for r,cs in horzs.items():
            lo,hi=min(cs),max(cs)
            if T and hi-lo>=T:
                for cc in range(lo,hi+1,T):
                    y,x=r,cc
                    if x not in ucols and out[y][x]!=v: out[y][x]=v
    return out
for n in (1,2,3):
    o=solve(G[f'Demo pair {n} input']); go=G[f'Demo pair {n} output']
    d=[(i,j,o[i][j],go[i][j]) for i in range(len(o)) for j in range(len(o[0])) if o[i][j]!=go[i][j]]
    print(n,'MATCH' if not d else d[:4], len(d))
